#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
const float nearCm = 100.0f;
bool dangerActive = false;
unsigned long eventStart = 0;
unsigned long lastSample = 0;

float readDistance(uint8_t trig, uint8_t echo) {
  digitalWrite(trig, LOW);
  delayMicroseconds(2);
  digitalWrite(trig, HIGH);
  delayMicroseconds(10);
  digitalWrite(trig, LOW);
  unsigned long us = pulseIn(echo, HIGH, 30000UL);
  return us ? us * 0.0343f / 2.0f : -1.0f;
}

void setup() {
  pinMode(8, OUTPUT);
  pinMode(9, INPUT);
  pinMode(10, OUTPUT);
  pinMode(11, INPUT);
  pinMode(12, OUTPUT);
  pinMode(13, OUTPUT);
  pinMode(6, OUTPUT);
  pinMode(2, OUTPUT);
  digitalWrite(2, LOW);
  digitalWrite(8, LOW);
  digitalWrite(10, LOW);
  digitalWrite(12, LOW);
  digitalWrite(13, HIGH);
  noTone(6);
  Serial.begin(9600);
  display.setBrightness(7);
  display.showNumberDec(0);
}

void loop() {
  unsigned long now = millis();
  if (now - lastSample >= 100UL) {
    lastSample = now;
    float vehicle = readDistance(8, 9);
    delay(3);
    float pedestrian = readDistance(10, 11);
    now = millis();
    bool danger = vehicle > 0 && vehicle < nearCm &&
                  pedestrian > 0 && pedestrian < nearCm;
    if (danger && !dangerActive) eventStart = now;
    if (!danger && dangerActive) {
      Serial.print("Last danger duration ms: ");
      Serial.println(now - eventStart);
    }
    dangerActive = danger;
    if (danger) {
      float nearest = vehicle < pedestrian ? vehicle : pedestrian;
      int level = nearest < 25 ? 3 : (nearest < 60 ? 2 : 1);
      display.showNumberDec(level);
      digitalWrite(13, LOW);
      tone(6, 1500);
    } else {
      display.showNumberDec(0);
      digitalWrite(13, HIGH);
      digitalWrite(12, LOW);
      noTone(6);
    }
  }
  if (dangerActive) {
    digitalWrite(12, ((millis() - eventStart) / 250UL) % 2 == 0 ? HIGH : LOW);
  }
}
